	/*
     * Adding a new tbl_jantri
     */
	function cutjantritemp($useNewView = false)
	{ //pr($_GET,1);
		date_default_timezone_set('Asia/Kolkata');
		$data['tbl_transactions'] = [];
		$data['sendjantri'] = 0;
		$pid = '';
		$date = '';
		$baseShiftId = '';
		$selectedDate = date('Y-m-d');
		$data['apply_commission'] = $useNewView && $this->input->get('apply_commission') === '1';
		$data['apply_patti'] = $useNewView && $this->input->get('apply_patti') === '1';
		if (isset($_GET) && !(empty($_GET))) {
			//echo '<pre>'; print_r($_GET); echo '</pre>';	die;
			$pid = $_GET['pid'];
			$date = $_GET['date'];
			$selectedDate = date('Y-m-d', strtotime($date));
			$shiftRow = $this->Tbl_shift_model->get_tbl_shift_usershift($pid);
			$baseShiftId = !empty($shiftRow['shift_id']) ? $shiftRow['shift_id'] : $pid;
			$resolvedTiming = $this->Tbl_shift_model->get_cutjantri_timing_for_shift(
				$this->session->userdata['id'],
				$baseShiftId,
				$date
			);
			if (!empty($resolvedTiming['id'])) {
				$pid = $resolvedTiming['id'];
			}
			$jandata =  $this->Tbl_shift_model->get_master_jantri_temp($pid,$date);
			//echo '<pre>'; print_r($jandata); echo '</pre>'; die;
			if($jandata){
			// $databaseTime = $jandata->mastertime; // Replace with your actual database time

			// // Convert database time to 24-hour format for comparison
			// $databaseTime24 = date('H:i', strtotime($databaseTime));

			// // Get current time in 24-hour format
			// $current24 = date('H:i');
			// //echo $databaseTime24.$current24; die;
			// if($jandata->open_date == date('Y-m-d') && ($databaseTime24 > $current24)){
			// 	$data['sendjantri'] = 1;	
			// } 
			// else{
			// 	$data['sendjantri'] = 0;
			// }
				// Define the date and time
			$dateString = $jandata->open_date.' '.$jandata->mastertime;

			// Create a DateTime object from the date string
			$dateTime = new DateTime($dateString);

			// Get the Unix timestamp
			$dbtimestamp = $dateTime->getTimestamp();

			$currtimestamp = time();

			if($currtimestamp < $dbtimestamp){
				$data['sendjantri'] = 1;	
			} 
				else{
					$data['sendjantri'] = 0;
				}

		}
			//$data['sendjantri'] =
			if($this->session->userdata['id'] != '1'){
				$data['tbl_transactions'] = $this->Tbl_transactions_model->get_custom_transactions_total_shift_master($pid, $date);
				if (empty($data['tbl_transactions'])) {
					$data['tbl_transactions'] = $this->Tbl_transactions_model->get_custom_transactions_total_shift($baseShiftId, $date);
				}
			}
			else{
				//$data['tbl_transactions'] = $this->Tbl_transactions_model->get_custom_transactions_total_shift_admin($pid, $date);
				//$data['tbl_transactions'] = $this->Tbl_transactions_model->view_transaction_filter($pid, $date);
				$data['todate'] = $date;
				$data['shift_name'] = $baseShiftId;
				$data['created_by'] = '1';
				//to correct admin jantri bringh data in same format as non admin
				$data['tbl_transactions'] = $this->Tbl_transactions_model->view_transaction_filter_admin($data);
				if (empty($data['tbl_transactions'])) {
					$data['tbl_transactions'] = $this->Tbl_transactions_model->get_custom_transactions_total_shift($baseShiftId, $date);
				}
			}
			
		}
		// Match the same ownership rules as the working transaction page.
		$shiftOwnerId = $this->session->userdata['id'];
		$timeColumn = 'master';
		if ($this->session->userdata['role'] == 'Staff') {
			$tbl_staff = $this->Tbl_staff_model->get_tbl_staff($this->session->userdata['id']);
			if (!empty($tbl_staff['updated_by'])) {
				$shiftOwnerId = $tbl_staff['updated_by'];
			}
			$timeColumn = 'data_entry_operator';
		}

		// Use the selected business date so historical cut-jantri pages can
		// resolve the same timing row that was active when the transactions were booked.
		$data['shifts'] = $this->Tbl_shift_model->get_cutjantri_shifts_for_date(
			$shiftOwnerId,
			$selectedDate,
			$timeColumn
		);
		if (empty($data['shifts'])) {
			$fallbackEndDate = date('Y-m-d', strtotime($selectedDate.' +1 day'));
			$data['shifts'] = $this->Tbl_shift_model->get_all_tbl_shift_master_for_trans(
				$shiftOwnerId,
				$selectedDate,
				$fallbackEndDate,
				$timeColumn
			);
		}
		if (empty($data['shifts'])) {
			$data['shifts'] = $this->Tbl_shift_model->get_all_tbl_shift_master($shiftOwnerId);
		}
		$data['selected_shift_id'] = $pid;
		$tbl_ledger_elements = $this->Tbl_ledger_model->get_tbl_ledger($this->session->userdata['id']);
		$data['ledger'] = $tbl_ledger_elements;
		//echo '<pre>'; print_r($jandata); echo '</pre>'; die;
		$data['_view'] = $useNewView
			? 'tbl_jantri/cut_index_temp'
			: 'tbl_jantri/cut_index_legacy';
		$this->load->view('layouts/main', $data);
	}

