	/*
     * Adding a new tbl_jantri
     */
	function add()
	{
		$this->load->library('form_validation');
		$data['error'] = '';
		$this->form_validation->set_rules('shift_name', 'Shift Name', 'max_length[255]');
		$this->form_validation->set_rules('next_day', 'Next Day', 'max_length[255]');
		$this->form_validation->set_rules('shift_working_for', 'Shift Working For', 'max_length[255]');
		$this->form_validation->set_rules('is_active', 'Is Active', 'integer');
		$this->form_validation->set_rules('updated_by', 'Updated By', 'integer');
		//echo '<pre>';print_r($this->session->userdata); die;
		//echo '<pre>';print_r($_POST); die;

		$mastr['shift_id'] = $_POST['shift'];
		$mastr['party_id'] = $_POST['party'];
		$mastr['t_date'] = date('Y-m-d', strtotime($_POST['tdate']));
		$mastr['total_number_amount'] = '';
		$mastr['total_akhar_amount'] = '';
		$tbl_transactions_id = $this->Tbl_transactions_model->add_tbl_transaction($mastr); //die;
		if ($tbl_transactions_id) { // echo $tbl_transactions_id; die;
			$tbl_master_transactions_id = $this->Tbl_transactions_model->add_jantri($tbl_transactions_id, $_POST);
			if ($tbl_master_transactions_id) {
				$this->session->set_flashdata('msg', 'Jantri Added');
				redirect('/transactions');
			}
		} else {
			return false;
		}
	}

	function partyjantri()
	{
		$data['tbl_transactions'] = [];
		if (isset($_GET) && !(empty($_GET))) {
			//echo '<pre>'; print_r($_GET); echo '</pre>';	die;
			$pid = $_GET['pid'];
			$date = $_GET['date'];
			$party = $_GET['partyid'];
			$data['tbl_transactions'] = $this->Tbl_transactions_model->get_custom_transactions_total_shift_party($pid, $date, $party);
		}
		//echo '<pre>'; print_r($data['tbl_transactions']); echo '</pre>'; die;
		$data['shifts'] = $this->Tbl_shift_model->get_all_tbl_shift_master($this->session->userdata['id']);
		$data['party'] = $this->Tbl_ledger_model->get_all_tbl_ledger_admin();
		//echo '<pre>';print_r($data); die;
		$data['_view'] = 'tbl_jantri/partyjantri';
		$this->load->view('layouts/main', $data);
	}

	/*
     * Editing a tbl_jantri
     */
	function edit($id)
	{
		// check if the tbl_jantri exists before trying to edit it
		$data['tbl_jantri'] = $this->Tbl_jantri_model->get_tbl_jantri($id);
		$data['error'] = '';
		if (isset($data['tbl_jantri']['id'])) {
			$this->load->library('form_validation');

			$this->form_validation->set_rules('shift_name', 'Shift Name', 'max_length[255]');
			$this->form_validation->set_rules('next_day', 'Next Day', 'max_length[255]');
			$this->form_validation->set_rules('shift_working_for', 'Shift Working For', 'max_length[255]');
			$this->form_validation->set_rules('is_active', 'Is Active', 'integer');
			$this->form_validation->set_rules('updated_by', 'Updated By', 'integer');

			if ($this->form_validation->run()) {
				//echo $this->Tbl_jantri_model->checkDuplicate($this->input->post('shift_name'),$this->session->userdata['id']); die;				
				if ($this->Tbl_jantri_model->checkDuplicate($this->input->post('shift_name'), $this->session->userdata['id']) == '1') {
					$data['error'] = "Duplicate Entry Found.Please try with other name.";
				} else {
					$params = array(
						'shift_name' => $this->input->post('shift_name'),
						'open_date' => $this->input->post('open_date'),
						'next_day' => $this->input->post('next_day'),
						'shift_working_for' => $this->input->post('shift_working_for'),
						'owner' => $this->input->post('owner'),
						'super_admin' => $this->input->post('super_admin'),
						'fanter' => $this->input->post('fanter'),
						'cash_agent' => $this->input->post('cash_agent'),
						'admin' => $this->input->post('admin'),
						'data_entry_operator' => $this->input->post('data_entry_operator'),
						'is_active' => $this->input->post('is_active'),
						'updated_by' => $this->session->userdata['id'],
						'updated_date' => $this->input->post('updated_date'),
					);

					$this->Tbl_jantri_model->update_tbl_jantri($id, $params);
					redirect('/shift_master');
				}
			}
			// else
			// {
			$data['_view'] = 'tbl_jantri/edit';
			$this->load->view('layouts/main', $data);
			// }
		} else
			show_error('The tbl_jantri you are trying to edit does not exist.');
	}

	/*
     * Deleting tbl_jantri
     */
	function remove($id)
	{
		$tbl_jantri = $this->Tbl_jantri_model->get_tbl_jantri($id);

		// check if the tbl_jantri exists before trying to delete it
		if (isset($tbl_jantri['id'])) {
			$this->Tbl_jantri_model->delete_tbl_jantri($id);
			redirect('shift_master');
		} else
			show_error('The tbl_jantri you are trying to delete does not exist.');
	}
